'use client';
// RESPONSIBILITY: Renders the Affiliates data table shell (header row + rows). Delegates each row to AffiliatesTableRow. No API calls.
import { useState } from 'react';
import AffiliatesTableRow from '@/app/superadmin/affiliates/affiliates_components/AffiliatesTable/AffiliatesTableRow';
import AffiliatesEmptyState from '@/app/superadmin/affiliates/affiliates_components/AffiliatesEmptyState/AffiliatesEmptyState';
import type { Affiliate, AffiliateStatus } from '@/app/superadmin/affiliates/affiliates_types/affiliates_types';
import SuperadminPagination from '@/app/superadmin/superadmin_components/SuperadminShared/SuperadminPagination';

interface AffiliatesTableProps {
  affiliates: Affiliate[];
  onToggleStatus: (id: string, currentStatus: AffiliateStatus) => void;
  onEdit: (affiliate: Affiliate) => void;
  onDelete: (id: string) => void;
  onAddClick: () => void;
}

const ITEMS_PER_PAGE = 10;

export default function AffiliatesTable({ affiliates, onToggleStatus, onEdit, onDelete, onAddClick }: AffiliatesTableProps) {
  const [currentPage, setCurrentPage] = useState(1);

  const totalPages = Math.ceil(affiliates.length / ITEMS_PER_PAGE) || 1;
  const paginatedAffiliates = affiliates.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  return (
    <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm flex flex-col min-h-[400px]">
      <div className="overflow-x-auto flex-1">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-primary/5 border-b border-border">
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Partner Name</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Referral Code</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Total Referred</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Commission Earned</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Status</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {paginatedAffiliates.length === 0 ? (
              <tr>
                <td colSpan={6}><AffiliatesEmptyState onAddClick={onAddClick} /></td>
              </tr>
            ) : (
              paginatedAffiliates.map((aff) => (
                <AffiliatesTableRow
                  key={aff.id}
                  affiliate={aff}
                  onToggleStatus={onToggleStatus}
                  onEdit={onEdit}
                  onDelete={onDelete}
                />
              ))
            )}
          </tbody>
        </table>
      </div>
      <SuperadminPagination 
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={setCurrentPage}
      />
    </div>
  );
}

// RESPONSIBILITY: Renders the Create/Edit Affiliate modal form. Receives form state via props from useAffiliatesPage. No API calls.
'use client';

import React from 'react';
import { X } from 'lucide-react';
import { UseFormReturn } from 'react-hook-form';
import type { AffiliateFormData } from '@/app/superadmin/affiliates/affiliates_types/affiliates_types';

interface SuperadminAffiliateModalProps {
  isOpen: boolean;
  onClose: () => void;
  form: UseFormReturn<AffiliateFormData>;
  onSubmit: (data: AffiliateFormData) => void;
  isEdit?: boolean;
  isMutating?: boolean;
}

export const SuperadminAffiliateModal: React.FC<SuperadminAffiliateModalProps> = ({
  isOpen,
  onClose,
  form,
  onSubmit,
  isEdit = false,
  isMutating = false,
}) => {
  if (!isOpen) return null;

  const { register, handleSubmit, formState: { errors } } = form;

  return (
    <div className="fixed inset-0 bg-black/60 z-40 flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-overlay border border-border rounded-2xl w-full max-w-md shadow-xl overflow-hidden flex flex-col">
        <div className="flex items-center justify-between px-7 py-5 border-b border-border">
          <h2 className="text-lg font-bold text-foreground">
            {isEdit ? 'Edit Affiliate Partner' : 'Add Affiliate Partner'}
          </h2>
          <button onClick={onClose} className="text-secondary hover:text-foreground motion-safe:transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>
        
        <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col p-7 gap-5 overflow-y-auto max-h-[70vh] custom-scrollbar">
          <div className="flex flex-col gap-1.5">
            <label className="text-sm font-bold text-secondary">Partner Name <span className="text-danger">*</span></label>
            <input 
              {...register('name')}
              className="w-full px-4 py-2.5 bg-input border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-border-focus motion-safe:transition-colors"
              placeholder="e.g. Fitness Gurus LLC"
            />
            {errors.name && <span className="text-xs text-danger">{errors.name.message}</span>}
          </div>

          <div className="flex flex-col gap-1.5">
            <label className="text-sm font-bold text-secondary">Email Address <span className="text-danger">*</span></label>
            <input 
              type="email" 
              {...register('email')}
              className="w-full px-4 py-2.5 bg-input border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-border-focus motion-safe:transition-colors"
              placeholder="partner@example.com"
            />
            {errors.email && <span className="text-xs text-danger">{errors.email.message}</span>}
          </div>

          <div className="flex flex-col gap-1.5">
            <label className="text-sm font-bold text-secondary">Custom Referral Code <span className="text-danger">*</span></label>
            <input 
              {...register('referralCode')}
              className="w-full px-4 py-2.5 bg-input border border-border rounded-lg text-sm text-foreground font-mono uppercase focus:outline-none focus:border-border-focus motion-safe:transition-colors"
              placeholder="e.g. PARTNER2026"
            />
            {errors.referralCode && <span className="text-xs text-danger">{errors.referralCode.message}</span>}
            <p className="text-xs text-secondary">Gyms using this code at checkout will be tracked to this partner.</p>
          </div>

          <div className="flex justify-end gap-3 mt-2 pt-5 border-t border-border">
            <button 
              type="button" 
              onClick={onClose}
              className="px-5 py-2.5 bg-transparent border border-border hover:bg-border text-foreground font-medium rounded-lg motion-safe:transition-colors text-sm"
            >
              Cancel
            </button>
            <button 
              type="submit" 
              disabled={isMutating}
              className="px-5 py-2.5 bg-primary hover:bg-primary-hover text-white font-medium rounded-lg motion-safe:transition-colors text-sm disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isMutating ? 'Saving...' : (isEdit ? 'Save Changes' : 'Save Partner')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

