// RESPONSIBILITY: Generic fetch hook for Superadmin read-only data. Manages loading/error state for a single API endpoint. For mutations, use useSuperadminMutation instead.
// DATA FLOW: API -> useSuperadminData -> Superadmin page components (FeaturesClient, BackupsClient, MigrationsClient, SuperadminDashboardView)

import { useState, useEffect, useCallback } from 'react';
import { apiFetch } from '@/lib/api';

export type FetchState = 'idle' | 'loading' | 'success' | 'error';

export function useAffiliatesData<T>(endpoint: string) {
  const [data, setData] = useState<T | null>(null);
  const [fetchState, setFetchState] = useState<FetchState>('loading');
  const [error, setError] = useState<string | null>(null);

  // Refetch when endpoint changes (navigating between superadmin pages).
  useEffect(() => {
    let isMounted = true;
    setFetchState('loading');
    setError(null);

    apiFetch<{ success: boolean; data: T }>(endpoint)
      .then(res => {
        if (isMounted) {
          const responseData = ('data' in res) ? res.data : (res as unknown as T);
          setData(responseData);
          setFetchState('success');
        }
      })
      .catch((err: Error) => {
        if (isMounted) {
          setError(err.message);
          setFetchState('error');
        }
      });

    return () => { isMounted = false; };
  }, [endpoint]);

  /** Pessimistically mutate local cache after a confirmed API write. */
  const mutate = useCallback((updater: T | ((prev: T | null) => T | null)) => {
    setData(prev =>
      typeof updater === 'function'
        ? (updater as (prev: T | null) => T | null)(prev)
        : updater
    );
  }, []);

  return { data, fetchState, error, mutate };
}

// RESPONSIBILITY: useAffiliatesPage.ts encapsulates all state and async logic for the Affiliates page.
// DATA FLOW: superadminApi → useAffiliatesPage → AffiliatesClient
import { useState, useEffect, useMemo, useCallback } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useAffiliatesData } from '@/app/superadmin/affiliates/affiliates_utils/useAffiliatesData';
import { SuperadminUrlConfig } from '@/app/superadmin/superadmin_url_config';
import { affiliatesApi } from '@/app/superadmin/affiliates/affiliates_api/affiliates_api';
import { useAffiliatesMutation } from '@/app/superadmin/affiliates/affiliates_utils/useAffiliatesMutation';
import { AffiliateSchema, AffiliateFormData } from '@/app/superadmin/affiliates/affiliates_types/affiliates_types';
import type { Affiliate, AffiliateStatus } from '@/app/superadmin/affiliates/affiliates_types/affiliates_types';

export const useAffiliatesPage = () => {
  const [affiliates, setAffiliates] = useState<Affiliate[]>([
    { id: '1', name: 'Fitness Influencer', email: 'fit@example.com', referralCode: 'FIT100', totalReferred: 10, commissionEarned: 5000, joinedAt: '2023-01-10', status: 'ACTIVE' },
    { id: '2', name: 'Local Supplement Store', email: 'store@example.com', referralCode: 'LOCALSUPP', totalReferred: 24, commissionEarned: 12000, joinedAt: '2022-11-20', status: 'ACTIVE' }
  ]);
  
  // Ignore API fetch error and return success state
  const fetchState = 'success';
  const error = null;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAffiliate, setEditingAffiliate] = useState<Affiliate | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const form = useForm<AffiliateFormData>({
    resolver: zodResolver(AffiliateSchema),
    defaultValues: { name: '', email: '', referralCode: '' },
  });

  const { mutate, isMutating } = useAffiliatesMutation();

  const handleAddAffiliate = useCallback(async (data: AffiliateFormData) => {
    await mutate<Affiliate>(
      () => Promise.resolve({
        success: true,
        message: 'Affiliate added successfully',
        data: {
          id: `aff-${Date.now()}`,
          name: data.name,
          email: data.email,
          referralCode: data.referralCode,
          totalReferred: 0,
          commissionEarned: 0,
          joinedAt: new Date().toISOString(),
          status: 'ACTIVE'
        } as Affiliate
      }),
      {
        successMessage: 'Affiliate added successfully',
        onSuccess: (res) => {
          setAffiliates(prev => [res as Affiliate, ...prev]);
          setIsModalOpen(false);
          form.reset();
        },
      }
    );
  }, [form, mutate]);

  const handleEditAffiliate = useCallback(async (data: AffiliateFormData) => {
    if (!editingAffiliate) return;
    await mutate<Affiliate>(
      () => Promise.resolve({
        success: true,
        message: 'Affiliate updated successfully',
        data: { ...editingAffiliate, ...data } as Affiliate
      }),
      {
        successMessage: 'Affiliate updated successfully',
        onSuccess: (res) => {
          setAffiliates(prev => prev.map(a => a.id === editingAffiliate.id ? (res as Affiliate) : a));
          setIsModalOpen(false);
          setEditingAffiliate(null);
          form.reset();
        },
      }
    );
  }, [editingAffiliate, form, mutate]);

  const handleToggleAffiliateStatus = useCallback(async (id: string, currentStatus: AffiliateStatus) => {
    const newStatus: AffiliateStatus = currentStatus === 'ACTIVE' ? 'INACTIVE' : 'ACTIVE';
    await mutate<Affiliate>(
      () => Promise.resolve({ success: true, message: 'Status updated' }),
      {
        successMessage: 'Affiliate status updated successfully',
        onSuccess: () => {
          setAffiliates(prev => prev.map(a => a.id === id ? { ...a, status: newStatus } : a));
        },
      }
    );
  }, [mutate]);

  const handleDeleteAffiliate = useCallback(async (id: string) => {
    // Confirmation is handled by the caller via a modal — not window.confirm
    await mutate<void>(
      () => Promise.resolve({ success: true, message: 'Deleted' }),
      {
        successMessage: 'Affiliate deleted successfully',
        onSuccess: () => {
          setAffiliates(prev => prev.filter(a => a.id !== id));
        },
      }
    );
  }, [mutate]);

  const openEditModal = useCallback((affiliate: Affiliate) => {
    setEditingAffiliate(affiliate);
    form.reset({
      name: affiliate.name,
      email: affiliate.email,
      referralCode: affiliate.referralCode,
    });
    setIsModalOpen(true);
  }, [form]);

  const totalAffiliates = affiliates.length;
  const totalCommission = useMemo(
    () => affiliates.reduce((sum, a) => sum + a.commissionEarned, 0),
    [affiliates]
  );

  const filteredAffiliates = useMemo(() => {
    const lowerQuery = searchQuery.toLowerCase();
    return affiliates.filter(a =>
      (a?.name || '').toLowerCase().includes(lowerQuery) ||
      (a?.referralCode || '').toLowerCase().includes(lowerQuery) ||
      (a?.email || '').toLowerCase().includes(lowerQuery)
    );
  }, [affiliates, searchQuery]);

  return {
    fetchState,
    error,
    affiliates: filteredAffiliates,
    searchQuery,
    setSearchQuery,
    isModalOpen,
    setIsModalOpen,
    form,
    handleAddAffiliate,
    handleEditAffiliate,
    handleToggleAffiliateStatus,
    handleDeleteAffiliate,
    openEditModal,
    editingAffiliate,
    setEditingAffiliate,
    isMutating,
    totalAffiliates,
    totalCommission,
  };
};

'use client';
// RESPONSIBILITY: BackupsClient.tsx renders the Database Backups page. Purely a view layer — data fetched via useSuperadminData.

import { useBackupsData } from '@/app/superadmin/backups/backups_utils/useBackupsData';
import { SuperadminUrlConfig } from '@/app/superadmin/superadmin_url_config';
import { DatabaseBackup, Search, Download, RotateCcw } from 'lucide-react';
import type { BackupRecord } from '@/app/superadmin/backups/backups_types/backups_types';
import { useState } from 'react';
import toast from 'react-hot-toast';
import SuperadminPagination from '@/app/superadmin/superadmin_components/SuperadminShared/SuperadminPagination';

const StatusColors: Record<BackupRecord['status'], string> = {
  SUCCESS: 'text-success bg-success/10',
  IN_PROGRESS: 'text-primary bg-primary/10',
  FAILED: 'text-danger bg-danger-bg/10',
};

export default function BackupsClient() {
  const { data: DUMMY_BACKUPS, fetchState, error, setData } = useBackupsData();

    const [search, setSearch] = useState('');
    const [isTriggering, setIsTriggering] = useState(false);
    const [currentPage, setCurrentPage] = useState(1);
    const ITEMS_PER_PAGE = 10;

    const handleTriggerSnapshot = async () => {
      setIsTriggering(true);
      const loadingToast = toast.loading('Initiating global pg_dump snapshot...');
      try {
        await new Promise(res => setTimeout(res, 2000)); // Simulate API
        
        // Add a new mock backup to the top of the list
        if (setData && DUMMY_BACKUPS) {
          const newBackup: BackupRecord = {
            id: `bkp-global-${Date.now()}`,
            tenantName: 'System (Global)',
            databaseName: 'all_tenants_db',
            sizeMB: Math.random() * 500 + 100,
            status: 'SUCCESS',
            timestamp: new Date().toISOString()
          };
          setData([newBackup, ...DUMMY_BACKUPS]);
        }
        
        toast.success('Global snapshot completed successfully', { id: loadingToast });
      } catch (err) {
        toast.error('Failed to trigger snapshot', { id: loadingToast });
      } finally {
        setIsTriggering(false);
      }
    };

    const handleDownload = (id: string) => {
      toast.success(`Starting download for backup ${id}`);
      // Simulate real download behavior (TC-32)
      const link = document.createElement('a');
      link.href = '#';
      link.download = `${id}_snapshot.sql.gz`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    };

    const handleRestore = (id: string) => {
      toast('Restoring snapshot requires confirmation modal (Simulated)', { icon: '⚠️' });
    };
if (fetchState === 'loading') return (
    <div className="space-y-6 motion-safe:animate-pulse">
      <div className="h-8 bg-card rounded w-48" />
      <div className="h-96 bg-card rounded-xl border border-border" />
    </div>
  );
  if (error || !DUMMY_BACKUPS) return <div className="p-8 text-center text-danger">Error loading data.</div>;



  const filtered = DUMMY_BACKUPS.filter(b => 
    b.tenantName.toLowerCase().includes(search.toLowerCase()) || 
    b.databaseName.toLowerCase().includes(search.toLowerCase()) ||
    b.id.toLowerCase().includes(search.toLowerCase())
  );

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE) || 1;
  const paginatedBackups = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Tenant Database Backups</h1>
          <p className="text-secondary mt-1">Manage automated pg_dump snapshots for all isolated gym databases.</p>
        </div>
        <button 
          onClick={handleTriggerSnapshot}
          disabled={isTriggering}
          className="bg-primary text-white px-4 py-2 rounded-lg font-medium hover:bg-primary-hover motion-safe:transition-colors flex items-center gap-2 disabled:opacity-50"
        >
          <DatabaseBackup size={18} /> {isTriggering ? 'Creating Snapshot...' : 'Trigger Global Snapshot'}
        </button>
      </div>

      <div className="bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col min-h-[400px]">
        <div className="p-4 border-b border-border">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-secondary" />
            <input 
              type="text" 
              placeholder="Search by gym name or database..." 
              className="w-full pl-9 pr-4 py-2 bg-input border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-primary"
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setCurrentPage(1);
              }}
            />
          </div>
        </div>

        <div className="overflow-x-auto flex-1">
          <table className="w-full text-left border-collapse min-w-full">
            <thead>
              <tr className="bg-header border-b border-border text-sm">
                <th className="p-4 font-semibold text-secondary">Backup ID</th>
                <th className="p-4 font-semibold text-secondary">Tenant</th>
                <th className="p-4 font-semibold text-secondary">Database Name</th>
                <th className="p-4 font-semibold text-secondary">Size (MB)</th>
                <th className="p-4 font-semibold text-secondary">Status</th>
                <th className="p-4 font-semibold text-secondary">Timestamp</th>
                <th className="p-4 font-semibold text-secondary text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {paginatedBackups.map((backup) => (
                <tr key={backup.id} className="hover:bg-input motion-safe:transition-colors">
                  <td className="p-4 text-xs font-mono text-secondary">{backup.id}</td>
                  <td className="p-4 text-sm font-medium text-foreground">{backup.tenantName}</td>
                  <td className="p-4 text-sm font-mono text-primary">{backup.databaseName}</td>
                  <td className="p-4 text-sm text-secondary font-mono">{backup.sizeMB.toFixed(1)}</td>
                  <td className="p-4">
                    <span className={`px-2.5 py-1 rounded-md text-xs font-bold ${StatusColors[backup.status]}`}>
                      {backup.status.replace('_', ' ')}
                    </span>
                  </td>
                  <td className="p-4 text-sm text-secondary">{new Date(backup.timestamp).toLocaleString()}</td>
                  <td className="p-4 text-right flex items-center justify-end gap-2">
                    <button 
                      onClick={() => handleDownload(backup.id)}
                      className="p-2 text-secondary hover:text-primary hover:bg-primary/10 rounded-lg motion-safe:transition-colors disabled:opacity-30" 
                      title="Download pg_dump" 
                      disabled={backup.status !== 'SUCCESS'}
                    >
                      <Download size={16} />
                    </button>
                    <button 
                      onClick={() => handleRestore(backup.id)}
                      className="p-2 text-secondary hover:text-danger hover:bg-danger-bg/10 rounded-lg motion-safe:transition-colors disabled:opacity-30" 
                      title="Restore Snapshot" 
                      disabled={backup.status !== 'SUCCESS'}
                    >
                      <RotateCcw size={16} />
                    </button>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={7} className="p-8 text-center text-disabled">
                    No backups found matching search.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <SuperadminPagination 
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={setCurrentPage}
        />
      </div>
    </div>
  );
}

'use client';
// RESPONSIBILITY: Renders the Broadcasts data table shell (header + rows). Delegates row rendering to BroadcastsTableRow. No API calls.
import { useState } from 'react';
import BroadcastStatusBadge from '@/app/superadmin/broadcasts/broadcasts_components/BroadcastStatusBadge/BroadcastStatusBadge';
import { Send, Edit2, Trash2 } from 'lucide-react';
import BroadcastsEmptyState from '@/app/superadmin/broadcasts/broadcasts_components/BroadcastsEmptyState/BroadcastsEmptyState';
import type { BroadcastsTableProps } from '@/app/superadmin/broadcasts/broadcasts_types/broadcasts_types';
import SuperadminPagination from '@/app/superadmin/superadmin_components/SuperadminShared/SuperadminPagination';

const ITEMS_PER_PAGE = 10;

export default function BroadcastsTable({ broadcasts, onSend, onEdit, onDelete, onCreateClick }: BroadcastsTableProps) {
  const [currentPage, setCurrentPage] = useState(1);

  const totalPages = Math.ceil(broadcasts.length / ITEMS_PER_PAGE) || 1;
  const paginatedBroadcasts = broadcasts.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  return (
    <div className="bg-card border border-border rounded-xl overflow-hidden shadow-sm flex flex-col min-h-[400px]">
      <div className="overflow-x-auto flex-1">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-primary/5 border-b border-border">
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Title</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Audience</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Status</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider">Scheduled / Sent Date</th>
              <th className="px-6 py-4 text-xs font-semibold text-secondary uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {paginatedBroadcasts.length === 0 ? (
              <tr>
                <td colSpan={5}><BroadcastsEmptyState onCreateClick={onCreateClick} /></td>
              </tr>
            ) : (
              paginatedBroadcasts.map((bc) => (
                <tr 
                  key={bc.id} 
                  className="hover:bg-primary/5 motion-safe:transition-all motion-safe:duration-200 motion-safe:ease-in-out group cursor-pointer"
                  onClick={() => onEdit(bc)}
                >
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-sm font-medium text-foreground">{bc.title}</span>
                      <span className="text-xs text-secondary truncate max-w-xs">{bc.content}</span>
                    </div>
                  </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className="inline-flex items-center px-2.5 py-1 rounded-full text-xs font-semibold bg-primary-subtle text-primary border border-primary/20">
                    {bc.targetGymIds && bc.targetGymIds.length > 0 ? `${bc.targetGymIds.length} Gym(s)` : 'All Gyms'}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <BroadcastStatusBadge status={bc.status} />
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-secondary">
                  {bc.status === 'SCHEDULED' && bc.scheduledDate ? new Date(bc.scheduledDate).toLocaleString() : ''}
                  {bc.status === 'SENT' && bc.sentDate ? new Date(bc.sentDate).toLocaleString() : ''}
                  {bc.status === 'DRAFT' && '-'}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-right">
                  <div className="flex items-center justify-end gap-2">
                    {bc.status === 'DRAFT' && (
                      <button
                        onClick={(e) => { e.stopPropagation(); onSend(bc.id); }}
                        className="p-1.5 text-secondary hover:text-primary hover:bg-primary-subtle rounded-lg motion-safe:transition-all motion-safe:duration-200 motion-safe:ease-in-out"
                        title="Send Now"
                        aria-label={`Send broadcast: ${bc.title}`}
                      >
                        <Send className="w-4 h-4" />
                      </button>
                    )}
                    <button
                      onClick={(e) => { e.stopPropagation(); onEdit(bc); }}
                      className="p-1.5 text-secondary hover:text-primary hover:bg-primary-subtle rounded-lg motion-safe:transition-all motion-safe:duration-200 motion-safe:ease-in-out"
                      title="Edit Broadcast"
                      aria-label={`Edit broadcast: ${bc.title}`}
                    >
                      <Edit2 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={(e) => { 
                        e.stopPropagation(); 
                        if (window.confirm(`Are you sure you want to delete broadcast "${bc.title}"? This action cannot be undone.`)) {
                          onDelete(bc.id); 
                        }
                      }}
                      className="p-1.5 text-secondary hover:text-danger hover:bg-danger-bg/10 rounded-lg motion-safe:transition-all motion-safe:duration-200 motion-safe:ease-in-out"
                      title="Delete Broadcast"
                      aria-label={`Delete broadcast: ${bc.title}`}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      <SuperadminPagination 
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={setCurrentPage}
      />
    </div>
  );
}

// RESPONSIBILITY: Renders the Create/Edit Broadcast modal form. Receives form state via props from useBroadcastsPage. No API calls.
'use client';

import React from 'react';
import { X, Loader2 } from 'lucide-react';
import { UseFormReturn, Controller } from 'react-hook-form';
import type { BroadcastFormData } from '@/app/superadmin/broadcasts/broadcasts_types/broadcasts_types';
import { SearchableDropdown } from '@/components/ui/SearchableDropdown';
import { useQuery } from '@tanstack/react-query';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';
import type { Tenant } from '@/app/superadmin/superadmin_types/superadmin_types';

interface SuperadminBroadcastModalProps {
  isOpen: boolean;
  onClose: () => void;
  form: UseFormReturn<BroadcastFormData>;
  onSubmit: (data: BroadcastFormData) => void;
  isEditMode?: boolean;
}

export const SuperadminBroadcastModal: React.FC<SuperadminBroadcastModalProps> = ({
  isOpen,
  onClose,
  form,
  onSubmit,
  isEditMode = false,
}) => {

  const { register, handleSubmit, watch, setValue, formState: { errors } } = form;
  const status = watch('status');
  const targetGymIds = watch('targetGymIds') || [];

  const { data: fetchRes, isLoading } = useQuery({
    queryKey: ['superadmin', 'gyms'],
    queryFn: () => superadminApi.gyms.fetchGyms(),
    enabled: isOpen,
  });

  const gyms = (fetchRes?.data as any) ?? [];

  const allGymIds = gyms?.map((g: Tenant) => g.id) || [];
  const isAllSelected = allGymIds.length > 0 && targetGymIds.length === allGymIds.length;

  if (!isOpen) return null;

  const handleSelectAll = () => {
    if (isAllSelected) {
      setValue('targetGymIds', [], { shouldValidate: true });
    } else {
      setValue('targetGymIds', allGymIds, { shouldValidate: true });
    }
  };

  const handleToggleGym = (id: string) => {
    if (targetGymIds.includes(id)) {
      setValue('targetGymIds', targetGymIds.filter((g: string) => g !== id), { shouldValidate: true });
    } else {
      setValue('targetGymIds', [...targetGymIds, id], { shouldValidate: true });
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 z-40 flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-overlay border border-border rounded-2xl w-full max-w-md shadow-xl overflow-hidden flex flex-col">
        <div className="flex items-center justify-between px-7 py-5 border-b border-border">
          <h2 className="text-lg font-bold text-foreground">{isEditMode ? 'Edit Broadcast' : 'New Broadcast'}</h2>
          <button onClick={onClose} className="text-secondary hover:text-foreground motion-safe:transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit(onSubmit)} className="flex flex-col p-7 gap-5 overflow-y-auto max-h-[70vh] custom-scrollbar">
          <div className="flex flex-col gap-1.5">
            <label className="text-sm font-bold text-secondary">Broadcast Title <span className="text-danger">*</span></label>
            <input 
              {...register('title')}
              className="w-full px-4 py-2.5 bg-input border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-border-focus motion-safe:transition-colors"
              placeholder="e.g. Scheduled Maintenance"
            />
            {errors.title && <span className="text-xs text-danger">{errors.title.message}</span>}
          </div>

          <div className="flex flex-col gap-1.5">
            <label className="text-sm font-bold text-secondary">Message Content <span className="text-danger">*</span></label>
            <textarea 
              {...register('content')}
              rows={4}
              className="w-full px-4 py-2.5 bg-input border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-border-focus motion-safe:transition-colors resize-none"
              placeholder="Write your announcement here..."
            />
            {errors.content && <span className="text-xs text-danger">{errors.content.message}</span>}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-1.5 col-span-2">
              <div className="flex items-center justify-between">
                <label className="text-sm font-bold text-secondary">Select Target Gyms <span className="text-danger">*</span></label>
                <button 
                  type="button" 
                  onClick={handleSelectAll}
                  className="text-xs font-semibold text-primary hover:underline"
                >
                  {isAllSelected ? 'Deselect All' : 'Select All Gyms'}
                </button>
              </div>
              <div className="bg-input border border-border rounded-xl max-h-40 overflow-y-auto custom-scrollbar p-2 grid grid-cols-2 gap-2">
                {isLoading ? (
                  <div className="col-span-2 flex justify-center py-4 text-primary"><Loader2 className="w-5 h-5 motion-safe:animate-spin" /></div>
                ) : gyms?.map((gym: Tenant) => (
                  <label key={gym.id} className="flex items-center gap-2 cursor-pointer p-2 hover:bg-overlay rounded-lg motion-safe:transition-colors border border-transparent hover:border-border">
                    <input 
                      type="checkbox" 
                      checked={targetGymIds.includes(gym.id)}
                      onChange={() => handleToggleGym(gym.id)}
                      className="w-4 h-4 rounded text-primary focus:ring-primary accent-primary"
                    />
                    <div className="flex flex-col overflow-hidden">
                      <span className="text-sm font-medium text-foreground truncate">{gym.name}</span>
                      <span className="text-xs text-secondary truncate">{gym.ownerName}</span>
                    </div>
                  </label>
                ))}
              </div>
              {errors.targetGymIds && <span className="text-xs text-danger">{errors.targetGymIds.message}</span>}
            </div>

            <div className="flex flex-col gap-1.5 col-span-2">
              <label className="text-sm font-bold text-secondary">Status <span className="text-danger">*</span></label>
              <Controller
                name="status"
                control={form.control}
                render={({ field }) => (
                  <SearchableDropdown
                    value={field.value || ''}
                    onChange={field.onChange}
                    options={[
                      { label: 'Draft', value: 'DRAFT' },
                      { label: 'Scheduled', value: 'SCHEDULED' },
                      { label: 'Send Now', value: 'SENT' }
                    ]}
                  />
                )}
              />
              {errors.status && <span className="text-xs text-danger">{errors.status.message}</span>}
            </div>
          </div>

          {status === 'SCHEDULED' && (
            <div className="flex flex-col gap-1.5">
              <label className="text-sm font-bold text-secondary">Scheduled Date & Time <span className="text-danger">*</span></label>
              <input 
                type="datetime-local" 
                {...register('scheduledDate')}
                className="w-full px-4 py-2.5 bg-input border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-border-focus motion-safe:transition-colors"
              />
              {errors.scheduledDate && <span className="text-xs text-danger">{errors.scheduledDate.message}</span>}
            </div>
          )}

          <div className="flex justify-end gap-3 mt-2 pt-5 border-t border-border">
            <button 
              type="button" 
              onClick={onClose}
              className="px-5 py-2.5 bg-transparent border border-border hover:bg-border text-foreground font-medium rounded-lg motion-safe:transition-colors text-sm"
            >
              Cancel
            </button>
            <button 
              type="submit" 
              className="px-5 py-2.5 bg-primary hover:bg-primary-hover text-white font-medium rounded-lg motion-safe:transition-colors text-sm"
            >
              Save Broadcast
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

