// RESPONSIBILITY: useCouponsPage.ts encapsulates all state and async logic for the Coupons page.
// DATA FLOW: superadminApi → useCouponsPage → CouponsClient
import { useState, useEffect, useMemo, useCallback } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import toast from 'react-hot-toast';
import { useCouponsData } from '@/app/superadmin/coupons/coupons_utils/useCouponsData';
import { SuperadminUrlConfig } from '@/app/superadmin/superadmin_url_config';
import { couponsApi } from '@/app/superadmin/coupons/coupons_api/coupons_api';
import { useCouponsMutation } from '@/app/superadmin/coupons/coupons_utils/useCouponsMutation';
import { CouponSchema, CouponFormData } from '@/app/superadmin/coupons/coupons_types/coupons_types';
import type { Coupon, CouponStatus } from '@/app/superadmin/coupons/coupons_types/coupons_types';
import { useLocalStorage } from '@/lib/useLocalStorage';

/** LocalStorage key for persisting coupon mutations across refreshes (TC-17/18 fix) */
const COUPONS_STORAGE_KEY = 'superadmin_coupons_v1';

export const useSuperadminCoupons = () => {
  const { data: fetchedData, fetchState, error } = useCouponsData<Coupon[]>(
    SuperadminUrlConfig.BACKEND_API.COUPONS_BASE
  );

  const [persistedCoupons, setPersistedCoupons] = useLocalStorage<Coupon[] | null>(COUPONS_STORAGE_KEY, null);
  const [coupons, setCoupons] = useState<Coupon[]>([]);

  // Sync fetched data into local state for pessimistic mutations, but respect localStorage
  useEffect(() => {
    if (fetchedData) {
      if (!persistedCoupons) {
        setPersistedCoupons(fetchedData);
        setCoupons(fetchedData);
      } else {
        setCoupons(persistedCoupons);
      }
    }
  }, [fetchedData, persistedCoupons, setPersistedCoupons]);

  const updateCoupons = useCallback((newCoupons: Coupon[] | ((prev: Coupon[]) => Coupon[])) => {
    setCoupons(prev => {
      const updated = typeof newCoupons === 'function' ? newCoupons(prev) : newCoupons;
      setPersistedCoupons(updated);
      return updated;
    });
  }, [setPersistedCoupons]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [selectedCoupon, setSelectedCoupon] = useState<Coupon | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeKpi, setActiveKpi] = useState<'ALL' | 'ACTIVE' | 'REDEEMED'>('ALL');

  const form = useForm<CouponFormData>({
    resolver: zodResolver(CouponSchema),
    defaultValues: {
      code: '',
      discountType: 'PERCENTAGE',
      discountValue: undefined,
      maxUses: undefined,
      expiryDate: '',
    },
  });

  const { mutate, isMutating } = useCouponsMutation();

  const handleCreateCoupon = useCallback(async (data: CouponFormData) => {
    // Mocking the backend API success as per "fix with all hardcoded data"
    const newCoupon = {
      id: `mock-${Date.now()}`,
      code: (data.code || `CODE-${Math.floor(Math.random() * 10000)}`).toUpperCase(),
      discountType: data.discountType,
      discountValue: data.discountValue || 0,
      maxUses: data.maxUses || 0,
      currentUses: 0,
      expiryDate: data.expiryDate,
      status: 'ACTIVE',
      isDeleted: false,
    } as Coupon;

    updateCoupons(prev => [newCoupon, ...prev]);
    setIsModalOpen(false);
    form.reset();
    toast.success('Coupon created successfully');
  }, [form, updateCoupons]);

  const handleUpdateCoupon = useCallback(async (id: string, data: Partial<CouponFormData>) => {
    if (!selectedCoupon) return;
    // Mocking update
    updateCoupons(prev => prev.map(c => c.id === id ? { ...c, ...data } as Coupon : c));
    setIsEditModalOpen(false);
    setSelectedCoupon(null);
    toast.success('Coupon updated successfully');
  }, [selectedCoupon, updateCoupons]);

  const handleDeleteCoupon = useCallback(async (id: string) => {
    // Mocking delete
    updateCoupons(prev => prev.filter(c => c.id !== id));
    toast.success('Coupon deleted successfully');
  }, [updateCoupons]);

  const handleToggleRestore = useCallback(async (id: string) => {
    // Mocking restore
    updateCoupons(prev => prev.map(c => c.id === id ? { ...c, isDeleted: false } : c));
    toast.success('Coupon restored successfully');
  }, [updateCoupons]);

  const handleToggleStatus = useCallback(async (id: string, currentStatus: CouponStatus) => {
    if (currentStatus !== 'ACTIVE' && currentStatus !== 'INACTIVE') {
      toast.error(`Cannot toggle status of ${currentStatus.toLowerCase()} coupon`);
      return;
    }
    const newStatus: CouponStatus = currentStatus === 'ACTIVE' ? 'INACTIVE' : 'ACTIVE';
    // Mocking toggle
    updateCoupons(prev => prev.map(c => c.id === id ? { ...c, status: newStatus } : c));
    toast.success(`Coupon marked as ${newStatus}`);
  }, [updateCoupons]);

  const activeCoupons = useMemo(
    () => coupons.filter(c => c.status === 'ACTIVE' && !c.isDeleted).length,
    [coupons]
  );
  const totalRedeemed = useMemo(
    () => coupons.reduce((sum, c) => sum + c.currentUses, 0),
    [coupons]
  );
  const totalCoupons = useMemo(() => coupons.length, [coupons]);

  const filteredCoupons = useMemo(() => {
    const lowerQuery = searchQuery.toLowerCase();
    return [...coupons]
      .filter(c => {
        if (activeKpi === 'ACTIVE') return c.status === 'ACTIVE' && !c.isDeleted;
        if (activeKpi === 'REDEEMED') return c.currentUses > 0;
        return true;
      })
      .sort((a, b) => {
        if (a.isDeleted && !b.isDeleted) return 1;
        if (!a.isDeleted && b.isDeleted) return -1;
        return 0;
      })
      .filter(c => c.code.toLowerCase().includes(lowerQuery));
  }, [coupons, searchQuery, activeKpi]);

  return {
    fetchState,
    error,
    coupons: filteredCoupons,
    searchQuery,
    setSearchQuery,
    isModalOpen,
    setIsModalOpen,
    form,
    handleCreateCoupon,
    isMutating,
    activeCoupons,
    totalRedeemed,
    isEditModalOpen,
    setIsEditModalOpen,
    selectedCoupon,
    setSelectedCoupon,
    handleUpdateCoupon,
    handleDeleteCoupon,
    handleToggleRestore,
    handleToggleStatus,
    activeKpi,
    setActiveKpi,
    totalCoupons,
  };
};

'use client';
// RESPONSIBILITY: SuperadminDashboardView.tsx renders the main SaaS metrics dashboard and charts. It receives data from the useSuperadminData hook.

import { Users, Building2, CreditCard, Activity } from 'lucide-react';
import dynamic from 'next/dynamic';
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';
import { SuperadminUrlConfig } from '@/app/superadmin/superadmin_url_config';
import { CHART_COLORS } from '@/app/superadmin/superadmin_utils/SuperadminChartConstants';
import type { SaaSDashboardMetrics, RevenueChartData, GrowthChartData, TimeRange } from '@/app/superadmin/dashboard/dashboard_types/dashboard_types';

const Chart = dynamic(() => import('react-apexcharts'), { ssr: false });

export default function SuperadminDashboardView() {
  const [timeRange, setTimeRange] = useState<TimeRange>('monthly');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const setCustomDateRange = (start: string, end: string) => {
    setStartDate(start);
    setEndDate(end);
  };
  
  const { data: fetchRes, isLoading, isError } = useQuery({
    queryKey: ['superadmin', 'dashboard'],
    queryFn: () => superadminApi.dashboard.fetchDashboardData(),
  });

  const data = fetchRes?.data as any; // Cast as any because the type from api is slightly different in the dummy response

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div>
          <div className="h-8 w-48 bg-border motion-safe:animate-pulse rounded"></div>
          <div className="h-4 w-96 bg-border motion-safe:animate-pulse rounded mt-2"></div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[1, 2, 3, 4].map((i) => (
            <div key={`skeleton-${i}`} className="bg-background border border-border rounded-xl p-6 h-32 motion-safe:animate-pulse"></div>
          ))}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-background border border-border rounded-xl p-6 h-80 motion-safe:animate-pulse"></div>
          <div className="bg-background border border-border rounded-xl p-6 h-80 motion-safe:animate-pulse"></div>
        </div>
      </div>
    );
  }

  if (isError || !data) return <div className="p-8 text-center text-danger font-medium">Error loading data.</div>;

  const { metrics: DUMMY_DASHBOARD_METRICS, revenue: REVENUE_CHART_DATA } = data;

  const timeMultiplier = timeRange === 'weekly' ? 0.25 : timeRange === 'yearly' ? 12 : timeRange === 'custom' ? 1.5 : 1;
  const mrrLabel = timeRange === 'weekly' ? 'WEEKLY RR' : timeRange === 'yearly' ? 'YEARLY RR' : timeRange === 'custom' ? 'CUSTOM RR' : 'TOTAL MRR';

  const metrics = [
    { label: mrrLabel, value: `₹${(Math.round((DUMMY_DASHBOARD_METRICS.monthlyRecurringRevenue || 0) * timeMultiplier)).toLocaleString('en-IN')}`, icon: CreditCard, color: 'text-success' },
    { label: 'TOTAL GYMS (TENANTS)', value: DUMMY_DASHBOARD_METRICS.totalGyms, icon: Building2, color: 'text-primary' },
    { label: 'ACTIVE GYMS', value: DUMMY_DASHBOARD_METRICS.activeGyms, icon: Activity, color: 'text-primary' },
    { label: 'TOTAL END USERS', value: (DUMMY_DASHBOARD_METRICS.totalEndUsers || 0).toLocaleString('en-IN'), icon: Users, color: 'text-purple' },
  ];

  const chartOptions = {
    chart: {
      type: 'area' as const,
      toolbar: { show: false },
      background: 'transparent',
    },
    colors: [CHART_COLORS.PRIMARY],
    fill: {
      type: 'gradient',
      gradient: {
        shadeIntensity: 1,
        opacityFrom: 0.4,
        opacityTo: 0.05,
        stops: [0, 90, 100]
      }
    },
    dataLabels: { enabled: false },
    stroke: { curve: 'smooth' as const, width: 2 },
    xaxis: {
      categories: REVENUE_CHART_DATA.map((d: RevenueChartData) => d.month),
      axisBorder: { show: false },
      axisTicks: { show: false },
      labels: { style: { colors: CHART_COLORS.TEXT_SECONDARY } }
    },
    yaxis: {
      labels: {
        style: { colors: CHART_COLORS.TEXT_SECONDARY },
        formatter: (val: number) => `₹${(val / 1000)}k`
      }
    },
    grid: {
      borderColor: CHART_COLORS.BORDER,
      strokeDashArray: 4,
    },
    theme: { mode: 'dark' as const },
    tooltip: {
      theme: 'dark' as const
    }
  };

  const chartSeries = [{
    name: mrrLabel,
    data: REVENUE_CHART_DATA.map((d: RevenueChartData) => Math.round(d.mrr * timeMultiplier))
  }];

  return (
    <div className="space-y-6">
      <div>
        <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4">
          <div>
            <h1 className="text-2xl font-bold text-foreground">
              SaaS Overview
            </h1>
            <p className="text-secondary mt-1 text-sm">Monitor the health and growth of your Multi-Tenant SaaS platform.</p>
          </div>
          <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
            {timeRange === 'custom' && (
              <div className="flex flex-wrap items-center gap-2 mr-2">
                <label className="text-sm font-medium text-secondary">From:</label>
                <input
                  type="date"
                  className="bg-input border border-border text-sm rounded-lg px-3 py-2 text-foreground focus:outline-none focus:border-primary"
                  value={startDate}
                  onChange={(e) => setCustomDateRange(e.target.value, endDate)}
                  aria-label="Start Date"
                />
                <label className="text-sm font-medium text-secondary ml-1">To:</label>
                <input
                  type="date"
                  className="bg-input border border-border text-sm rounded-lg px-3 py-2 text-foreground focus:outline-none focus:border-primary"
                  value={endDate}
                  onChange={(e) => setCustomDateRange(startDate, e.target.value)}
                  aria-label="End Date"
                />
              </div>
            )}
            <select 
              value={timeRange} 
              onChange={(e) => {
                setTimeRange(e.target.value as TimeRange);
                if (e.target.value !== 'custom') {
                  setCustomDateRange('', '');
                }
              }}
              className="bg-input border border-border text-sm rounded-lg px-3 py-2 text-foreground focus:outline-none focus:border-primary"
            >
              <option value="weekly">This Week</option>
              <option value="monthly">This Month</option>
              <option value="yearly">This Year</option>
              <option value="custom">Custom Range</option>
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {metrics.map((m) => (
          <div key={m.label} className="bg-card border border-border rounded-xl p-6 shadow-sm motion-safe:hover:-translate-y-1 motion-safe:hover:shadow-lg motion-safe:transition-all motion-safe:duration-200 motion-safe:ease-in-out">
            <div className="flex items-center justify-between mb-4">
              <span className="text-secondary font-medium text-xs uppercase tracking-wider">{m.label}</span>
              <m.icon className={`w-5 h-5 ${m.color}`} />
            </div>
            <div className="text-3xl font-bold text-foreground">{m.value}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-card border border-border rounded-xl p-6 shadow-sm">
          <h2 className="text-base font-semibold text-foreground mb-6">{mrrLabel} Growth</h2>
          <div className="h-80 w-full">
            <Chart options={chartOptions} series={chartSeries} type="area" height="100%" />
          </div>
        </div>

        <div className="bg-card border border-border rounded-xl p-6 shadow-sm">
          <h2 className="text-base font-semibold text-foreground mb-6">Recent Onboards</h2>
          <div className="space-y-4">
            {DUMMY_DASHBOARD_METRICS.recentOnboards.map((tenant: any) => (
              <div key={tenant.id} className="flex items-center justify-between p-4 bg-background rounded-lg border border-border hover:bg-input motion-safe:transition-colors motion-safe:duration-200 cursor-default">
                <div>
                  <h3 className="text-sm font-semibold text-foreground truncate max-w-32" title={tenant.name}>{tenant.name}</h3>
                  <p className="text-xs text-secondary mt-1 truncate max-w-32" title={tenant.ownerName}>{tenant.ownerName}</p>
                </div>
                <div className="text-right flex flex-col items-end">
                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold
                    ${
                      tenant.plan?.toUpperCase() === 'ENTERPRISE' ? 'bg-purple-bg text-purple border border-purple' : 
                      tenant.plan?.toUpperCase() === 'PRO' ? 'bg-primary-subtle text-primary border border-primary' : 
                      tenant.plan?.toUpperCase() === 'STARTER' || tenant.plan?.toUpperCase() === 'BASIC' ? 'bg-success-bg text-success border border-success' :
                      'bg-input text-secondary border border-border'
                    }
                  `}>
                    {tenant.plan?.toUpperCase() || 'UNKNOWN'}
                  </span>
                  <p className="text-xs text-disabled mt-2">{tenant.createdAt}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

// RESPONSIBILITY: Defines all TypeScript types and interfaces for the Dashboard module.
export type TenantStatus = 'ACTIVE' | 'SUSPENDED' | 'TRIAL' | 'CANCELLED';

export type FetchState = 'idle' | 'loading' | 'success' | 'error';
export type TimeRange = 'weekly' | 'monthly' | 'yearly' | 'custom';

export interface DashboardContextType { 
