// RESPONSIBILITY: Hook to manage the state and logic of the GymDeleteModal.
// DATA FLOW: GymDeleteModal -> useGymDeleteModal -> API

import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { useQueryClient, useMutation } from '@tanstack/react-query';
import { useGymsStore } from '@/app/superadmin/gyms/gyms_store/useGymsStore';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';

export function useGymDeleteModal() {
  const isDeleteModalOpen = useGymsStore(state => state.isDeleteModalOpen);
  const closeDeleteModal = useGymsStore(state => state.closeDeleteModal);
  const gymToDelete = useGymsStore(state => state.gymToDelete);

  const queryClient = useQueryClient();

  const [confirmText, setConfirmText] = useState('');

  // Reset confirmation text whenever the modal opens or closes
  useEffect(() => {
    if (!isDeleteModalOpen) {
      setConfirmText('');
    }
  }, [isDeleteModalOpen]);

  const deleteMutation = useMutation({
    mutationFn: (id: string) => superadminApi.gyms.deleteGym(id),
    onSuccess: (res) => {
      toast.success(res.message || 'Tenant deleted successfully.');
      queryClient.invalidateQueries({ queryKey: ['superadmin', 'gyms'] });
      closeDeleteModal();
    },
    onError: (err: any) => {
      toast.error(err.message || 'Failed to delete tenant');
    }
  });

  const handleConfirmDelete = () => {
    if (confirmText === 'DELETE' && gymToDelete) {
      deleteMutation.mutate(gymToDelete.id);
    }
  };

  return {
    isDeleteModalOpen,
    closeDeleteModal,
    gymToDelete,
    confirmText,
    setConfirmText,
    handleConfirmDelete,
    actionLoadingId: deleteMutation.isPending ? gymToDelete?.id : null
  };
}

// RESPONSIBILITY: Handles form validation, modal state, and API submission for editing a Gym.
// DATA FLOW: GymEditModal -> useGymEditModal -> API

import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import toast from 'react-hot-toast';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useGymsStore } from '@/app/superadmin/gyms/gyms_store/useGymsStore';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';

const gymEditSchema = z.object({
  name: z.string().min(1, 'Gym Name is required'),
  ownerName: z.string().min(1, 'Owner Name is required'),
  adminEmail: z.string().email('Invalid email address'),
  phone: z.string().min(10, 'Valid phone number required'),
  plan: z.string().min(1, 'Please select a plan'),
  temporaryPassword: z.string().optional().refine(val => !val || val.length >= 8, {
    message: "Password must be at least 8 characters",
  }),
});

type GymEditFormValues = z.infer<typeof gymEditSchema>;

export function useGymEditModal() {
  const isEditModalOpen = useGymsStore(state => state.isEditModalOpen);
  const closeEditModal = useGymsStore(state => state.closeEditModal);
  const selectedGym = useGymsStore(state => state.selectedGym);

  const queryClient = useQueryClient();

  const { data: fetchRes, isLoading: loadingPlans } = useQuery({
    queryKey: ['superadmin', 'plans'],
    queryFn: () => superadminApi.plans.fetchPlans(),
  });

  const plans = fetchRes?.data || [];

  const {
    register,
    handleSubmit,
    reset,
    control,
    formState: { errors, isSubmitting },
  } = useForm<GymEditFormValues>({
    resolver: zodResolver(gymEditSchema),
  });

  useEffect(() => {
    if (selectedGym && isEditModalOpen) {
      reset({
        name: selectedGym.name,
        ownerName: selectedGym.ownerName,
        adminEmail: selectedGym.adminEmail,
        phone: selectedGym.phone,
        plan: selectedGym.plan,
        temporaryPassword: '',
      });
    }
  }, [selectedGym, isEditModalOpen, reset]);

  const editMutation = useMutation({
    mutationFn: (data: GymEditFormValues) => superadminApi.gyms.updateGym(selectedGym!.id, data),
    onSuccess: (res) => {
      toast.success(res.message || 'Gym details updated successfully.');
      queryClient.invalidateQueries({ queryKey: ['superadmin', 'gyms'] });
      closeEditModal();
    },
    onError: (err: any) => {
      toast.error(err.message || 'Failed to update gym details.');
    }
  });

  const onSubmit = async (data: GymEditFormValues) => {
    if (selectedGym) {
      editMutation.mutate(data);
    }
  };

  return {
    isEditModalOpen,
    closeEditModal,
    selectedGym,
    plans,
    loadingPlans,
    register,
    handleSubmit,
    onSubmit,
    control,
    errors,
    isSubmitting: isSubmitting || editMutation.isPending,
  };
}

