// RESPONSIBILITY: Handles form validation, modal state, and API submission for sending a WhatsApp message to a Gym owner.
// DATA FLOW: GymWhatsappModal -> useGymWhatsappModal -> API

import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import toast from 'react-hot-toast';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useGymsStore } from '@/app/superadmin/gyms/gyms_store/useGymsStore';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';
import { WhatsAppFormatter } from '@/lib/whatsapp_formatter';

const gymWhatsappSchema = z.object({
  subject: z.string().min(1, 'Subject is required'),
  message: z.string().min(1, 'Message is required'),
});

type GymWhatsappFormValues = z.infer<typeof gymWhatsappSchema>;

export function useGymWhatsappModal() {
  const isWhatsappModalOpen = useGymsStore(state => state.isWhatsappModalOpen);
  const closeWhatsappModal = useGymsStore(state => state.closeWhatsappModal);
  const selectedGym = useGymsStore(state => state.selectedGym);

  const queryClient = useQueryClient();

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<GymWhatsappFormValues>({
    resolver: zodResolver(gymWhatsappSchema),
  });

  useEffect(() => {
    if (isWhatsappModalOpen) {
      reset({ subject: '', message: '' });
    }
  }, [isWhatsappModalOpen, reset]);

  const whatsappMutation = useMutation({
    mutationFn: (data: GymWhatsappFormValues & { phone: string; ownerName: string; gymName: string }) => 
      superadminApi.gyms.emailGymOwner(selectedGym!.id, data), // Still calling API for record keeping if necessary, or just skip
    onSuccess: (res, data) => {
      if (data.phone) {
        const cleanPhone = String(data.phone).replace(/\D/g, '');
        const dateStr = new Intl.DateTimeFormat('en-IN', {
          day: '2-digit', month: 'short', year: 'numeric',
          hour: '2-digit', minute: '2-digit', hour12: true
        }).format(new Date());

        const waText = WhatsAppFormatter.formatReceipt({
          title: 'Smart Gym 360',
          subtitle: String(data.subject),
          date: dateStr,
          customerInfo: {
            Owner: String(data.ownerName || 'Gym Owner'),
            Gym: String(data.gymName || 'Gym')
          },
          sections: [
            {
              title: 'Message',
              items: {
                'Content': String(data.message)
              }
            }
          ],
          footer: 'Powered by Smart Gym 360'
        });

        window.open(`https://wa.me/${cleanPhone}?text=${encodeURIComponent(waText)}`, '_blank');
      }

      toast.success(res.message || 'WhatsApp opened successfully.');
      closeWhatsappModal();
    },
    onError: (err: any) => {
      toast.error(err.message || 'Failed to send WhatsApp message.');
    }
  });

  const onSubmit = async (data: GymWhatsappFormValues) => {
    if (selectedGym) {
      whatsappMutation.mutate({ 
        ...data, 
        phone: selectedGym.phone,
        ownerName: selectedGym.ownerName,
        gymName: selectedGym.name
      });
    }
  };

  return {
    isWhatsappModalOpen,
    closeWhatsappModal,
    selectedGym,
    register,
    handleSubmit,
    onSubmit,
    errors,
    isSubmitting: isSubmitting || whatsappMutation.isPending,
  };
}

'use client';
// RESPONSIBILITY: Renders the table view of Gym tenants. Purely a view component that consumes useGymsTable hook.

import { useState } from 'react';
import { CheckCircle2, Ban, LogIn, PlayCircle, Edit2, MessageCircle, Trash2, Loader2 } from 'lucide-react';
import { useGymsTable } from '@/app/superadmin/gyms/gyms_components/GymsTable/useGymsTable';
import GymEditModal from '@/app/superadmin/gyms/gyms_components/GymEditModal/GymEditModal';
import GymWhatsappModal from '@/app/superadmin/gyms/gyms_components/GymWhatsappModal/GymWhatsappModal';
import GymDeleteModal from '@/app/superadmin/gyms/gyms_components/GymDeleteModal/GymDeleteModal';
import GymsEmptyState from '@/app/superadmin/gyms/gyms_components/GymsEmptyState/GymsEmptyState';
import SuperadminPagination from '@/app/superadmin/superadmin_components/SuperadminShared/SuperadminPagination';
import { GYMS_TABLE_PAGE_SIZE } from '@/app/superadmin/gyms/gyms_utils/GymsConstants';

export default function GymsTable() {
  const {
    filteredGyms,
    fetchState,
    actionLoadingId,
    handleRowClick,
    onGhostLoginClick,
    onSuspendClick,
    onDeleteClick,
    openEditModal,
    openWhatsappModal
  } = useGymsTable();

  const [currentPage, setCurrentPage] = useState(1);

  if (fetchState === 'loading') {
    return (
      <div className="p-4 space-y-4">
        {[...Array(5)].map((_, i) => (
          <div key={`skeleton-${i}`} className="h-12 bg-card motion-safe:animate-pulse rounded-lg border border-border" />
        ))}
      </div>
    );
  }

  if (fetchState === 'error') {
    return <div className="p-8 text-center text-danger">Error loading gyms. Please try again.</div>;
  }

  const totalPages = Math.ceil(filteredGyms.length / GYMS_TABLE_PAGE_SIZE) || 1;
  const paginatedGyms = filteredGyms.slice((currentPage - 1) * GYMS_TABLE_PAGE_SIZE, currentPage * GYMS_TABLE_PAGE_SIZE);

  return (
