  const DUMMY_BACKGROUND_JOBS: BackgroundJob[] = rawJobs.length > 0 ? rawJobs : [
    { id: 'job-1', queueName: 'billing', jobName: 'Process Monthly Invoices', status: 'ACTIVE', attempts: 1, createdAt: new Date().toISOString() },
    { id: 'job-2', queueName: 'email', jobName: 'Send Welcome Email', status: 'FAILED', attempts: 3, error: 'Connection timeout', createdAt: new Date(Date.now() - 3600000).toISOString() },
    { id: 'job-3', queueName: 'database', jobName: 'Nightly Backup', status: 'COMPLETED', attempts: 1, createdAt: new Date(Date.now() - 86400000).toISOString() },
  ];

  const handleRetryAll = () => {
    setIsRetrying(true);
    toast.promise(
      new Promise(resolve => setTimeout(resolve, 1500)),
      {
        loading: 'Retrying all failed jobs...',
        success: 'Successfully queued all failed jobs for retry.',
        error: 'Failed to retry jobs.'
      }
    ).finally(() => setIsRetrying(false));
  };

  const handleRetryJob = (id: string) => {
    toast.success(`Job ${id} queued for retry.`);
  };

  const handleCancelJob = (id: string) => {
    toast.success(`Job ${id} cancelled successfully.`);
  };

  const handleDeleteJob = (id: string) => {
    toast.success(`Job ${id} deleted.`);
    setSelectedJobIds(prev => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  const handleClearCompleted = () => {
    toast.success('Cleared all completed jobs.');
    setSelectedJobIds(new Set());
  };

  const handleBulkRetry = () => {
    toast.success(`Queued ${selectedJobIds.size} jobs for retry.`);
    setSelectedJobIds(new Set());
  };

  const handleBulkDelete = () => {
    toast.success(`Deleted ${selectedJobIds.size} jobs.`);
    setSelectedJobIds(new Set());
  };

  const toggleSelection = (id: string) => {
    setSelectedJobIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const toggleAll = (visibleJobIds: string[]) => {
    if (selectedJobIds.size === visibleJobIds.length && visibleJobIds.length > 0) {
      setSelectedJobIds(new Set());
    } else {
      setSelectedJobIds(new Set(visibleJobIds));
    }
  };

  if (isLoading) return <div className="flex h-96 items-center justify-center"><Loader2 className="w-8 h-8 motion-safe:animate-spin text-primary" /></div>;
  if (isError) return <div className="p-8 text-center text-danger">Error loading data.</div>;

  const filteredJobs = DUMMY_BACKGROUND_JOBS.filter(job => {
    if (statusFilter !== 'ALL' && job.status !== statusFilter) return false;
    if (queueFilter !== 'ALL' && job.queueName !== queueFilter) return false;
    return true;
  });

  const totalPages = Math.ceil(filteredJobs.length / ITEMS_PER_PAGE) || 1;
  const paginatedJobs = filteredJobs.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  const formatDuration = (ms?: number) => {
    if (!ms) return '-';
    if (ms < 1000) return `${ms}ms`;
    return `${(ms / 1000).toFixed(2)}s`;
  };

  return (
    <div className="space-y-6 motion-safe:animate-in motion-safe:fade-in">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-foreground">Background Jobs</h1>
          <p className="text-secondary mt-1">Monitor async queues, inspect payloads, and manage tasks.</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={handleClearCompleted}
            className="bg-input text-foreground px-4 py-2 rounded-lg font-medium hover:bg-border motion-safe:transition-colors border border-border"
          >
            Clear Completed
          </button>
          <button 
            onClick={handleRetryAll}
            disabled={isRetrying}
            className="bg-danger-bg/10 text-danger px-4 py-2 rounded-lg font-medium hover:bg-danger-bg hover:text-white motion-safe:transition-colors flex items-center gap-2 border border-destructive/20 hover:border-transparent disabled:opacity-50"
          >
            <RefreshCw size={16} className={isRetrying ? "motion-safe:animate-spin" : ""} /> Retry All Failed
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
        {[
          { label: 'Active Jobs', value: metrics?.activeJobs || 0, icon: Play, color: 'text-primary' },
          { label: 'Completed (24h)', value: metrics?.completed24h || 0, icon: Activity, color: 'text-success' },
          { label: 'Failed (24h)', value: metrics?.failed24h || 0, icon: XCircle, color: 'text-danger' },
          { label: 'Delayed', value: metrics?.delayed || 0, icon: AlertTriangle, color: 'text-warning' }
        ].map(stat => (
          <div key={stat.label} className="bg-card border border-border rounded-xl p-4 flex items-center gap-4">
            <div className={`p-3 rounded-lg bg-input ${stat.color}`}>
              <stat.icon size={24} />
            </div>
            <div>
              <p className="text-sm text-secondary font-medium">{stat.label}</p>
              <p className={`text-2xl font-bold ${stat.color}`}>{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Filters & Bulk Actions Bar */}
      <div className="bg-card border border-border rounded-xl p-4 flex flex-col sm:flex-row items-center justify-between gap-4 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Filter size={16} className="text-secondary" />
            <select 
              className="bg-input border border-border text-foreground text-sm rounded-lg px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-primary"
              value={statusFilter}
              onChange={(e) => { setStatusFilter(e.target.value); setCurrentPage(1); }}
            >
              <option value="ALL">All Statuses</option>
              <option value="FAILED">Failed</option>
              <option value="ACTIVE">Active</option>
              <option value="COMPLETED">Completed</option>
              <option value="DELAYED">Delayed</option>
            </select>
          </div>
          <select 
            className="bg-input border border-border text-foreground text-sm rounded-lg px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-primary"
            value={queueFilter}
            onChange={(e) => { setQueueFilter(e.target.value); setCurrentPage(1); }}
          >
            <option value="ALL">All Queues</option>
            <option value="billing">billing</option>
            <option value="email">email</option>
            <option value="webhook">webhook</option>
            <option value="database">database</option>
          </select>
        </div>

        {selectedJobIds.size > 0 && (
          <div className="flex items-center gap-3 motion-safe:animate-in slide-in-from-right-4">
            <span className="text-sm font-medium text-primary mr-2">{selectedJobIds.size} selected</span>
            <button 
              onClick={handleBulkRetry}
              className="flex items-center gap-1.5 bg-primary text-white px-3 py-1.5 rounded-md text-sm hover:bg-primary-hover motion-safe:transition-colors"
            >
              <RefreshCw size={14} /> Retry
            </button>
            <button 
              onClick={handleBulkDelete}
              className="flex items-center gap-1.5 bg-danger-bg text-white px-3 py-1.5 rounded-md text-sm hover:opacity-90 motion-safe:transition-opacity"
            >
              <Trash2 size={14} /> Delete
            </button>
          </div>
        )}
      </div>

      <div className="bg-card border border-border rounded-xl shadow-sm overflow-hidden flex flex-col min-h-[400px]">
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-left border-collapse min-w-full">
            <thead>
              <tr className="bg-header border-b border-border text-sm">
                <th className="p-4 w-12 text-center">
                  <input 
                    type="checkbox" 
                    className="rounded border-border text-primary focus:ring-primary cursor-pointer w-4 h-4"
                    checked={selectedJobIds.size === paginatedJobs.length && paginatedJobs.length > 0}
                    onChange={() => toggleAll(paginatedJobs.map(j => j.id))}
                  />
                </th>
                <th className="p-4 font-semibold text-secondary">Job ID</th>
                <th className="p-4 font-semibold text-secondary">Queue</th>
                <th className="p-4 font-semibold text-secondary">Task / Error</th>
                <th className="p-4 font-semibold text-secondary">Status</th>
                <th className="p-4 font-semibold text-secondary">Timing</th>
                <th className="p-4 font-semibold text-secondary text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {paginatedJobs.length === 0 ? (
                <tr>
                  <td colSpan={7} className="p-8 text-center text-secondary">No jobs found matching the criteria.</td>
                </tr>
              ) : paginatedJobs.map((job) => (
                <tr key={job.id} onClick={() => setInspectJob(job)} className="hover:bg-input motion-safe:transition-colors group cursor-pointer">
                  <td className="p-4 text-center">
                    <input 
                      type="checkbox" 
                      className="rounded border-border text-primary focus:ring-primary cursor-pointer w-4 h-4"
                      checked={selectedJobIds.has(job.id)}
                      onChange={() => toggleSelection(job.id)}
                    />
                  </td>
                  <td className="p-4 text-xs font-mono text-secondary">{job.id}</td>
                  <td className="p-4 text-sm font-medium text-primary">{job.queueName}</td>
                  <td className="p-4 text-sm max-w-[200px]">
                    <div className="font-medium text-foreground">{job.jobName}</div>
                    {job.error && <div className="text-xs text-danger truncate mt-1" title={job.error}>{job.error}</div>}
                  </td>
                  <td className="p-4">
                    <div className="flex flex-col items-start gap-1">
                      <span className={`px-2.5 py-1 rounded-md text-xs font-bold ${StatusColors[job.status]}`}>
                        {job.status}
                      </span>
                      {job.attempts > 1 && <span className="text-[10px] text-secondary">Attempts: {job.attempts}</span>}
                    </div>
                  </td>
                  <td className="p-4 text-xs text-secondary whitespace-nowrap">
                    <div>Created: {new Date(job.createdAt).toLocaleTimeString()}</div>
                    {/* @ts-ignore */}
                    {job.finishedAt && <div>Finished: {new Date(job.finishedAt).toLocaleTimeString()}</div>}
                    {/* @ts-ignore */}
                    <div className="font-mono mt-1 text-foreground">Duration: {formatDuration(job.durationMs)}</div>
                  </td>
                  <td className="p-4 text-right">
                    <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 motion-safe:transition-opacity">

                      {job.status === 'FAILED' && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); handleRetryJob(job.id); }}
                          className="p-1.5 text-secondary hover:text-primary hover:bg-primary/10 rounded-lg motion-safe:transition-colors"
                          title="Retry Job"
                        >
                          <RefreshCw size={16} />
                        </button>
                      )}

                      {(job.status === 'ACTIVE' || job.status === 'DELAYED') && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); handleCancelJob(job.id); }}
                          className="p-1.5 text-secondary hover:text-warning hover:bg-warning/10 rounded-lg motion-safe:transition-colors"
                          title="Cancel Job"
                        >
                          <XCircle size={16} />
                        </button>
                      )}

                      <button 
                        onClick={(e) => { e.stopPropagation(); handleDeleteJob(job.id); }}
                        className="p-1.5 text-secondary hover:text-danger hover:bg-danger-bg/10 rounded-lg motion-safe:transition-colors"
                        title="Delete Job"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <SuperadminPagination 
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={setCurrentPage}
        />
      </div>

      {/* Payload Inspect Modal */}
      {inspectJob && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm motion-safe:animate-in motion-safe:fade-in">
          <div className="bg-card border border-border rounded-2xl w-full max-w-2xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh]">
            <div className="flex items-center justify-between px-6 py-5 border-b border-border bg-sidebar/30">
              <div>
                <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
                  <Eye className="text-primary w-5 h-5" /> Inspect Job: {inspectJob.id}
                </h2>
                <p className="text-sm text-secondary mt-1">Queue: {inspectJob.queueName} | Task: {inspectJob.jobName}</p>
              </div>
              <button onClick={() => setInspectJob(null)} className="p-2 text-secondary hover:text-foreground hover:bg-input rounded-full motion-safe:transition-colors">
                <XIcon className="w-5 h-5" />
              </button>
            </div>
            <div className="p-6 overflow-y-auto custom-scrollbar flex-1 space-y-6">

              <div>
                <h3 className="text-sm font-semibold text-secondary mb-2 uppercase tracking-wider">Status & Timing</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 bg-input p-4 rounded-lg">
                  <div><p className="text-xs text-secondary mb-1">Status</p><p className={`text-sm font-bold ${StatusColors[inspectJob.status as BackgroundJob['status']].split(' ')[0]}`}>{inspectJob.status}</p></div>
                  <div><p className="text-xs text-secondary mb-1">Attempts</p><p className="text-sm font-medium text-foreground">{inspectJob.attempts}</p></div>
                  <div><p className="text-xs text-secondary mb-1">Created At</p><p className="text-sm text-foreground">{new Date(inspectJob.createdAt).toLocaleString()}</p></div>
                  <div><p className="text-xs text-secondary mb-1">Duration</p><p className="text-sm text-foreground font-mono">{formatDuration(inspectJob.durationMs)}</p></div>
                </div>
              </div>

              {inspectJob.error && (
                <div>
                  <h3 className="text-sm font-semibold text-danger mb-2 uppercase tracking-wider flex items-center gap-1"><AlertTriangle size={14}/> Error Trace</h3>
                  <div className="bg-danger-bg/10 border border-destructive/20 text-danger p-4 rounded-lg text-sm font-mono overflow-x-auto whitespace-pre-wrap">
                    {inspectJob.error}
                  </div>
                </div>
              )}

              <div>
                <h3 className="text-sm font-semibold text-primary mb-2 uppercase tracking-wider">Job Payload</h3>
                <div className="bg-sidebar border border-border p-4 rounded-lg overflow-x-auto">
                  <pre className="text-xs font-mono text-foreground">
                    {JSON.stringify(inspectJob.payload || { message: "No payload attached." }, null, 2)}
                  </pre>
                </div>
              </div>

            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// RESPONSIBILITY: PlansClient.tsx is the root client entry for the Plans page. Initialises the Zustand store on mount.
'use client';

import { useEffect } from 'react';
import { usePlansStore } from '@/app/superadmin/plans/plans_store/usePlansStore';
import PlansList from '@/app/superadmin/plans/plans_components/PlansList';
import PlanCreateModal from '@/app/superadmin/plans/plans_components/PlanCreateModal';
import PlanEditModal from '@/app/superadmin/plans/plans_components/PlanEditModal';

export default function PlansClient() {
  const openCreateModal = usePlansStore(state => state.openCreateModal);

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-foreground">Subscription Plans</h1>
          <p className="text-secondary mt-1">Manage pricing tiers and limits for SaaS tenants.</p>
        </div>
        <button
          onClick={openCreateModal}
          className="bg-primary text-white px-4 py-2 rounded-lg font-medium hover:bg-primary-hover motion-safe:transition-colors motion-safe:active:scale-95"
        >
          Create New Plan
        </button>
      </div>

      <PlansList />
      <PlanCreateModal />
      <PlanEditModal />
    </div>
  );
}

// RESPONSIBILITY: Renders the modal form for creating a new subscription plan. Reads/writes via usePlansStore.
'use client';

import { useForm, useFieldArray } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { X, Plus, Trash2, Loader2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { useQueryClient, useMutation } from '@tanstack/react-query';
import { usePlansStore } from '@/app/superadmin/plans/plans_store/usePlansStore';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';

const planSchema = z.object({
  name: z.string().min(1, 'Plan Name is required'),
  priceMonthly: z.coerce.number().min(0),
  priceAnnual: z.coerce.number().min(0),
  maxMembers: z.coerce.number().min(1),
  maxStaff: z.coerce.number().min(1),
  features: z.array(z.object({ value: z.string().min(1, 'Feature cannot be empty') })).min(1),
});

type PlanFormValues = z.infer<typeof planSchema>;

export default function PlanCreateModal() {
  const isOpen = usePlansStore(state => state.isCreateModalOpen);
  const closeCreateModal = usePlansStore(state => state.closeCreateModal);

  const queryClient = useQueryClient();

  const { register, control, handleSubmit, formState: { errors }, reset } = useForm<PlanFormValues>({
    resolver: zodResolver(planSchema) as any,
    defaultValues: {
      name: '', priceMonthly: 0, priceAnnual: 0, maxMembers: 100, maxStaff: 5,
      features: [{ value: 'Core Gym Management' }],
    },
  });

  const { fields, append, remove } = useFieldArray({ control, name: 'features' });

  const createMutation = useMutation({
    mutationFn: (data: any) => superadminApi.plans.createPlan(data),
    onSuccess: (res) => {
      toast.success(res.message || 'Plan created successfully');
      queryClient.invalidateQueries({ queryKey: ['superadmin', 'plans'] });
      reset();
      closeCreateModal();
    },
    onError: (err: any) => {
      toast.error(err.message || 'Failed to create plan');
    }
  });

  const isSubmitting = createMutation.isPending;

  if (!isOpen) return null;

  const handleClose = () => { reset(); closeCreateModal(); };

  const onSubmit = async (data: PlanFormValues) => {
    createMutation.mutate({ ...data, features: data.features.map(f => f.value) });
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-overlay border border-border rounded-2xl w-full max-w-2xl max-h-screen overflow-hidden flex flex-col shadow-2xl shadow-black/50">
        <div className="flex items-center justify-between p-6 border-b border-border">
          <h2 className="text-xl font-bold text-foreground">Create New Subscription Plan</h2>
          <button onClick={handleClose} className="p-2 hover:bg-input rounded-full motion-safe:transition-colors text-secondary" aria-label="Close modal">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit(onSubmit)} className="flex-1 overflow-y-auto p-6 space-y-6">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-secondary">Plan Name <span className="text-danger">*</span></label>
            <input {...register('name')} placeholder="e.g. Pro Tier" className="w-full bg-input border border-border rounded-xl px-4 py-3 text-foreground focus:border-primary outline-none motion-safe:transition-colors" />
            {errors.name && <p className="text-danger text-xs">{errors.name.message}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
            {(['priceMonthly', 'priceAnnual'] as const).map(field => (
              <div key={field} className="space-y-2">
                <label className="block text-sm font-medium text-secondary">{field === 'priceMonthly' ? 'Monthly Price (₹)' : 'Annual Price (₹)'} <span className="text-danger">*</span></label>
                <input type="number" min="0" onKeyDown={(e) => { if (e.key === '-' || e.key === 'e' || e.key === '+') e.preventDefault(); }} step="0.01" {...register(field, { valueAsNumber: true })} className="w-full bg-input border border-border rounded-xl px-4 py-3 text-foreground focus:border-primary outline-none motion-safe:transition-colors" />
                {errors[field] && <p className="text-danger text-xs">{errors[field]?.message}</p>}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-2 gap-4">
            {(['maxMembers', 'maxStaff'] as const).map(field => (
              <div key={field} className="space-y-2">
                <label className="block text-sm font-medium text-secondary">{field === 'maxMembers' ? 'Max Members' : 'Max Staff'} <span className="text-danger">*</span></label>
                <input type="number" min="0" onKeyDown={(e) => { if (e.key === '-' || e.key === 'e' || e.key === '+') e.preventDefault(); }} {...register(field, { valueAsNumber: true })} className="w-full bg-input border border-border rounded-xl px-4 py-3 text-foreground focus:border-primary outline-none motion-safe:transition-colors" />
                {errors[field] && <p className="text-danger text-xs">{errors[field]?.message}</p>}
              </div>
            ))}
          </div>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <label className="block text-sm font-medium text-secondary">Features List <span className="text-danger">*</span></label>
              <button type="button" onClick={() => append({ value: '' })} className="flex items-center gap-1 text-sm text-primary hover:text-primary-hover font-medium">
                <Plus size={16} /> Add Feature
              </button>
            </div>
            {fields.map((field, index) => (
              <div key={field.id} className="flex flex-wrap items-center gap-2">
                <input {...register(`features.${index}.value`)} placeholder="e.g. Advanced Analytics" className="flex-1 bg-input border border-border rounded-xl px-4 py-2.5 text-foreground focus:border-primary outline-none motion-safe:transition-colors" />
                {fields.length > 1 && (
                  <button type="button" onClick={() => remove(index)} className="p-2.5 text-secondary hover:text-danger hover:bg-danger/10 rounded-xl motion-safe:transition-colors" aria-label="Remove feature">
                    <Trash2 size={18} />
                  </button>
                )}
              </div>
            ))}
          </div>
        </form>

        <div className="p-6 border-t border-border bg-sidebar flex justify-end gap-3">
          <button type="button" onClick={handleClose} className="px-6 py-2.5 rounded-xl font-medium text-secondary hover:bg-input motion-safe:transition-colors">Cancel</button>
          <button onClick={handleSubmit(onSubmit)} disabled={isSubmitting} className="px-6 py-2.5 rounded-xl font-medium bg-primary text-white hover:bg-primary-hover motion-safe:transition-colors disabled:opacity-50 flex items-center gap-2 motion-safe:active:scale-95">
            {isSubmitting ? <><Loader2 size={16} className="motion-safe:animate-spin" /> Creating...</> : 'Create Plan'}
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';
// RESPONSIBILITY: Renders the modal form for editing an existing subscription plan. Reads/writes via usePlansStore.

import { useEffect } from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { X, Plus, Trash2, Loader2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { useQueryClient, useMutation } from '@tanstack/react-query';
import { usePlansStore } from '@/app/superadmin/plans/plans_store/usePlansStore';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';

const planSchema = z.object({
  name: z.string().min(1, 'Plan Name is required'),
  priceMonthly: z.coerce.number().min(0),
  priceAnnual: z.coerce.number().min(0),
  maxMembers: z.coerce.number().min(1),
  maxStaff: z.coerce.number().min(1),
  features: z.array(z.object({ value: z.string().min(1, 'Feature cannot be empty') })).min(1),
});

type PlanFormValues = z.infer<typeof planSchema>;

export default function PlanEditModal() {
  const isOpen = usePlansStore(state => state.isEditModalOpen);
  const closeEditModal = usePlansStore(state => state.closeEditModal);
  const selectedPlan = usePlansStore(state => state.selectedPlan);

  const queryClient = useQueryClient();

  const { register, control, handleSubmit, formState: { errors }, reset } = useForm<PlanFormValues>({
    resolver: zodResolver(planSchema) as any,
  });

  const { fields, append, remove } = useFieldArray({ control, name: 'features' });

  // Populate form when selectedPlan changes
  useEffect(() => {
    if (selectedPlan && isOpen) {
      reset({
        name: selectedPlan.name,
        priceMonthly: selectedPlan.priceMonthly,
        priceAnnual: selectedPlan.priceAnnual,
        maxMembers: selectedPlan.maxMembers,
        maxStaff: selectedPlan.maxStaff,
        features: selectedPlan.features?.length > 0
          ? selectedPlan.features.map(f => ({ value: f }))
          : [{ value: 'Core Gym Management' }],
      });
    }
  }, [selectedPlan, isOpen, reset]);

  const editMutation = useMutation({
    mutationFn: (data: any) => superadminApi.plans.updatePlan(selectedPlan!.id, data),
    onSuccess: (res) => {
      toast.success(res.message || 'Plan updated successfully');
      queryClient.invalidateQueries({ queryKey: ['superadmin', 'plans'] });
      closeEditModal();
    },
    onError: (err: any) => {
      toast.error(err.message || 'Failed to update plan');
    }
  });

  const isSubmitting = editMutation.isPending;

  if (!isOpen || !selectedPlan) return null;

  const onSubmit = async (data: PlanFormValues) => {
    editMutation.mutate({ ...data, features: data.features.map(f => f.value) });
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-overlay border border-border rounded-2xl w-full max-w-2xl max-h-screen overflow-hidden flex flex-col shadow-2xl shadow-black/50">
        <div className="flex items-center justify-between p-6 border-b border-border">
          <h2 className="text-xl font-bold text-foreground">Edit Subscription Plan</h2>
          <button onClick={closeEditModal} className="p-2 hover:bg-input rounded-full motion-safe:transition-colors text-secondary" aria-label="Close modal">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit(onSubmit)} className="flex-1 overflow-y-auto p-6 space-y-6">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-secondary">Plan Name <span className="text-danger">*</span></label>
            <input {...register('name')} placeholder="e.g. Pro Tier" className="w-full bg-input border border-border rounded-xl px-4 py-3 text-foreground focus:border-primary outline-none motion-safe:transition-colors" />
            {errors.name && <p className="text-danger text-xs">{errors.name.message}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
            {(['priceMonthly', 'priceAnnual'] as const).map(field => (
              <div key={field} className="space-y-2">
                <label className="block text-sm font-medium text-secondary">{field === 'priceMonthly' ? 'Monthly Price (₹)' : 'Annual Price (₹)'} <span className="text-danger">*</span></label>
                <input type="number" min="0" onKeyDown={(e) => { if (e.key === '-' || e.key === 'e' || e.key === '+') e.preventDefault(); }} step="0.01" {...register(field, { valueAsNumber: true })} className="w-full bg-input border border-border rounded-xl px-4 py-3 text-foreground focus:border-primary outline-none motion-safe:transition-colors" />
                {errors[field] && <p className="text-danger text-xs">{errors[field]?.message}</p>}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-2 gap-4">
            {(['maxMembers', 'maxStaff'] as const).map(field => (
              <div key={field} className="space-y-2">
                <label className="block text-sm font-medium text-secondary">{field === 'maxMembers' ? 'Max Members' : 'Max Staff'} <span className="text-danger">*</span></label>
                <input type="number" min="0" onKeyDown={(e) => { if (e.key === '-' || e.key === 'e' || e.key === '+') e.preventDefault(); }} {...register(field, { valueAsNumber: true })} className="w-full bg-input border border-border rounded-xl px-4 py-3 text-foreground focus:border-primary outline-none motion-safe:transition-colors" />
                {errors[field] && <p className="text-danger text-xs">{errors[field]?.message}</p>}
              </div>
            ))}
          </div>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <label className="block text-sm font-medium text-secondary">Features List <span className="text-danger">*</span></label>
              <button type="button" onClick={() => append({ value: '' })} className="flex items-center gap-1 text-sm text-primary hover:text-primary-hover font-medium">
                <Plus size={16} /> Add Feature
              </button>
            </div>
            {fields.map((field, index) => (
              <div key={field.id} className="flex flex-wrap items-center gap-2">
                <input {...register(`features.${index}.value`)} placeholder="e.g. Advanced Analytics" className="flex-1 bg-input border border-border rounded-xl px-4 py-2.5 text-foreground focus:border-primary outline-none motion-safe:transition-colors" />
                {fields.length > 1 && (
                  <button type="button" onClick={() => remove(index)} className="p-2.5 text-secondary hover:text-danger hover:bg-danger/10 rounded-xl motion-safe:transition-colors" aria-label="Remove feature">
                    <Trash2 size={18} />
                  </button>
                )}
              </div>
            ))}
          </div>
        </form>

        <div className="p-6 border-t border-border bg-sidebar flex justify-end gap-3">
          <button type="button" onClick={closeEditModal} className="px-6 py-2.5 rounded-xl font-medium text-secondary hover:bg-input motion-safe:transition-colors">Cancel</button>
          <button onClick={handleSubmit(onSubmit)} disabled={isSubmitting} className="px-6 py-2.5 rounded-xl font-medium bg-primary text-white hover:bg-primary-hover motion-safe:transition-colors disabled:opacity-50 flex items-center gap-2 motion-safe:active:scale-95">
            {isSubmitting ? <><Loader2 size={16} className="motion-safe:animate-spin" /> Saving...</> : 'Save Changes'}
          </button>
        </div>
      </div>
    </div>
  );
}

// RESPONSIBILITY: Renders the grid of subscription plan cards using TanStack Query.
// DATA FLOW: superadminApi -> useQuery -> PlansList

'use client';

import { Check, Edit2, Trash2, Loader2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';
import { usePlansStore } from '@/app/superadmin/plans/plans_store/usePlansStore';

export default function PlansList() {
  const openEditModal = usePlansStore(state => state.openEditModal);
  const queryClient = useQueryClient();

  const { data: fetchRes, isLoading, isError } = useQuery({
    queryKey: ['superadmin', 'plans'],
    queryFn: () => superadminApi.plans.fetchPlans(),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => superadminApi.plans.deletePlan(id),
    onSuccess: (res) => {
      toast.success(res.message || 'Plan deleted');
      queryClient.invalidateQueries({ queryKey: ['superadmin', 'plans'] });
    },
    onError: (err: any) => {
      toast.error(err.message || 'Failed to delete plan');
    }
  });

  const plans = fetchRes?.data || [];

  if (isLoading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {[...Array(3)].map((_, i) => (
          <div key={`skeleton-${i}`} className="h-64 bg-card border border-border rounded-2xl motion-safe:animate-pulse" />
        ))}
      </div>
    );
  }

  if (isError) {
    return <div className="p-8 text-center text-danger">Error loading plans.</div>;
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
      {plans.map((plan) => {
        const isDeleting = deleteMutation.isPending && deleteMutation.variables === plan.id;
        return (
          <div
            key={plan.id}
            className="bg-card border border-border rounded-2xl p-6 flex flex-col relative overflow-hidden group hover:border-primary motion-safe:transition-colors motion-safe:duration-200"
          >
            <div className="absolute top-0 right-0 bg-primary/10 text-primary px-3 py-1 text-xs font-bold rounded-bl-lg">
              {plan.activeTenants ?? 0} Gyms Active
            </div>

            <div className="mb-4">
              <h2 className="text-xl font-bold text-foreground">{plan.name}</h2>
              <div className="flex items-end gap-1 mt-2">
                <span className="text-3xl font-extrabold text-foreground">₹{Number(plan.priceMonthly).toFixed(2)}</span>
                <span className="text-secondary font-medium mb-1">/ mo</span>
              </div>
            </div>

            <div className="space-y-3 flex-1 mb-6">
              <p className="text-sm text-secondary font-medium pb-2 border-b border-border">
                Max Members: <span className="text-foreground">{plan.maxMembers}</span>
              </p>
              <p className="text-sm text-secondary font-medium pb-2 border-b border-border">
                Max Staff: <span className="text-foreground">{plan.maxStaff}</span>
              </p>
              <div className="pt-2">
                {plan.features?.map((feat) => (
                  <div key={feat} className="flex items-center gap-2 mb-2 text-sm text-secondary">
                    <Check className="w-4 h-4 text-success shrink-0" />
                    {feat}
                  </div>
                ))}
              </div>
            </div>

            <div className="flex gap-2">
              <button
                onClick={() => openEditModal(plan)}
                disabled={isDeleting || deleteMutation.isPending}
                aria-label={`Edit ${plan.name}`}
                className="flex-1 py-2.5 flex items-center justify-center bg-input hover:bg-primary hover:text-white text-foreground rounded-xl motion-safe:transition-colors border border-border disabled:opacity-50"
              >
                <Edit2 size={18} />
              </button>
              <button
                onClick={() => {
                  if (window.confirm(`Are you sure you want to delete the plan "${plan.name}"? This action cannot be undone.`)) {
                    deleteMutation.mutate(plan.id);
                  }
                }}
                disabled={isDeleting || deleteMutation.isPending}
                aria-label={`Delete ${plan.name}`}
                className="flex-1 py-2.5 flex items-center justify-center bg-input hover:bg-danger hover:text-white text-secondary rounded-xl motion-safe:transition-colors border border-border disabled:opacity-50"
              >
                {isDeleting ? <Loader2 size={18} className="motion-safe:animate-spin" /> : <Trash2 size={18} />}
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// RESPONSIBILITY: Renders the Platform Settings page. Fetches settings from API and allows inline editing per setting using TanStack Query.
'use client';

import { useState } from 'react';
import { Settings, BellRing, Loader2, Save } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { superadminApi } from '@/app/superadmin/superadmin_api/superadmin_api';
import toast from 'react-hot-toast';
import { SearchableDropdown } from '@/components/ui/SearchableDropdown';
import type { PlatformSetting } from '@/app/superadmin/superadmin_types/superadmin_types';

const mockSettings: PlatformSetting[] = [
  { id: '1', key: 'MAX_MEMBERS_PER_GYM', value: '1000', description: 'Default maximum members for new tenants', category: 'general', dataType: 'number' },
  { id: '2', key: 'MAX_BRANCHES', value: '5', description: 'Default maximum branches allowed', category: 'general', dataType: 'number' },
  { id: '3', key: 'SYSTEM_CURRENCY', value: 'INR', description: 'Default currency for billing', category: 'general', dataType: 'string' },
  { id: '4', key: 'ENABLE_BETA_FEATURES', value: 'false', description: 'Toggle experimental features globally', category: 'general', dataType: 'boolean' }
];

export default function SettingsClient() {
  const [editedValues, setEditedValues] = useState<Record<string, string>>({});
  const queryClient = useQueryClient();

  const { data: fetchRes, isLoading, isError } = useQuery({
    queryKey: ['superadmin', 'settings'],
    queryFn: () => superadminApi.settings.fetchSettings(),
  });

  const settings = fetchRes?.data && fetchRes.data.length > 0 ? fetchRes.data : mockSettings;

  const updateMutation = useMutation({
    mutationFn: ({ id, value }: { id: string, value: string }) => superadminApi.settings.updateSetting(id, { value }),
    onSuccess: (res, variables) => {
      toast.success(res.message || 'Setting updated successfully');
      queryClient.setQueryData(['superadmin', 'settings'], (old: any) => {
        if (!old?.data) return old;
        return {
          ...old,
          data: old.data.map((s: PlatformSetting) => s.id === variables.id ? { ...s, value: variables.value } : s)
        };
      });
      setEditedValues(prev => {
        const next = { ...prev };
        delete next[variables.id];
        return next;
      });
    },
    onError: (err: any) => {
      toast.error(err.message || 'Failed to update setting');
    }
  });

  const handleSave = (id: string) => {
    const newValue = editedValues[id];
    if (newValue === undefined) return;
    updateMutation.mutate({ id, value: newValue });
  };

  if (isLoading) {
    return <div className="flex h-96 items-center justify-center"><Loader2 className="w-8 h-8 motion-safe:animate-spin text-primary" /></div>;
  }

  if (isError) {
    return <div className="flex h-96 items-center justify-center text-danger font-medium">Error loading settings.</div>;
  }

  const groupedSettings = settings.reduce<Record<string, PlatformSetting[]>>((acc, curr) => {
    const cat = curr.category || 'general';
    if (!acc[cat]) acc[cat] = [];
    acc[cat].push(curr);
    return acc;
  }, {});

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-foreground">Platform Settings</h1>
        <p className="text-secondary mt-1">Configure global SaaS limits, master credentials, and system defaults.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          {Object.entries(groupedSettings).map(([category, items]) => (
            <div key={category} className="bg-card border border-border rounded-xl p-6">
              <div className="flex items-center gap-2 mb-4 border-b border-border pb-4">
                <Settings className="w-5 h-5 text-primary" />
                <h2 className="text-lg font-bold text-foreground uppercase">{category}</h2>
              </div>

              <div className="space-y-4 text-sm">
                {items.map(setting => {
                  const hasChanges = editedValues[setting.id] !== undefined && editedValues[setting.id] !== setting.value;
                  const currentValue = editedValues[setting.id] !== undefined ? editedValues[setting.id] : setting.value;

                  return (
                    <div key={setting.id} className="flex flex-col md:flex-row md:items-center justify-between gap-4 py-2 border-b border-border last:border-0">
                      <div className="flex-1">
                        <h3 className="font-medium text-foreground">{setting.key}</h3>
                        <p className="text-xs text-secondary mt-1">{setting.description}</p>
                      </div>
                      <div className="flex flex-wrap items-center gap-2">
                        {setting.dataType === 'boolean' ? (
                          <SearchableDropdown
                            value={String(currentValue)}
                            onChange={(val) => setEditedValues(prev => ({ ...prev, [setting.id]: String(val) }))}
                            className="w-32"
                            options={[
                              { label: 'Enabled', value: 'true' },
                              { label: 'Disabled', value: 'false' }
                            ]}
                          />
                        ) : (
                          <input
                            type={setting.dataType === 'number' ? 'number' : 'text'}
                            value={currentValue}
                            onChange={(e) => setEditedValues(prev => ({ ...prev, [setting.id]: e.target.value }))}
                            className="bg-input border border-border text-foreground rounded-lg px-3 py-1.5 focus:outline-none focus:border-primary"
                          />
                        )}
                        {hasChanges && (
                          <button
                            onClick={() => handleSave(setting.id)}
                            disabled={updateMutation.isPending && updateMutation.variables?.id === setting.id}
                            className="p-1.5 bg-primary/10 text-primary hover:bg-primary hover:text-white rounded-lg motion-safe:transition-colors"
                          >
                            <Save className="w-4 h-4" />
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>

        <div className="space-y-6">
          <div className="bg-card border border-border rounded-xl p-6">
            <div className="flex items-center gap-2 mb-4 border-b border-border pb-4">
              <BellRing className="w-5 h-5 text-warning" />
              <h2 className="text-lg font-bold text-foreground">Global Broadcast</h2>
            </div>
            <p className="text-sm text-secondary mb-4">Send a push notification to all Admins across all 50+ gyms.</p>
            <textarea
              disabled
              placeholder="e.g. System maintenance at 2AM EST..."
              className="w-full bg-input border border-border text-disabled rounded-lg px-4 py-2 h-24 resize-none cursor-not-allowed"
            />
            <button disabled className="mt-2 w-full bg-primary/50 text-white font-medium py-2 rounded-lg cursor-not-allowed">
              Broadcast Message
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// RESPONSIBILITY: Modularized API client for the Superadmin module. All methods import apiFetch from src/lib/api.ts and define only superadmin-scoped endpoints. No UI logic.
